/** Fixed iTunes storefronts; the order per query is chosen by script, and release verification confirms the set (see docs/deployment/todos.md). */
export const ITUNES_STOREFRONTS = ['jp', 'us', 'kr', 'tw'] as const;
export type ItunesStorefront = typeof ITUNES_STOREFRONTS[number];

export type LookupDate = ImportDate;

/*
 * Evidence types. They are internal: a later administrator DTO must allowlist them and never
 * expose `artworkUrl`. Text is raw (bounded and free of lone surrogates); NFC normalization and
 * the automatic-draft text rules are applied when values are written into a draft.
 */
export type LookupArtistCredit = { name: string; joinPhrase: string; artistId: string; artistName: string };
export type LookupLabel = { name: string | null; labelId: string | null; catalogNumber: string | null };
export type MusicBrainzReleaseSummary = {
    releaseId: string; releaseGroupId: string | null; title: string; status: string | null;
    artistCredit: LookupArtistCredit[]; labels: LookupLabel[];
    /** Normalized GTIN digits, or null when absent, malformed or a placeholder. */
    barcode: string | null; barcodeText: string | null;
    country: string | null; date: LookupDate | null; primaryType: string | null; secondaryTypes: string[];
    trackCount: number; media: { format: string | null; trackCount: number }[]; score: number | null;
};
export type MusicBrainzTrack = { position: number; number: string; title: string; lengthMs: number | null; recordingId: string; isrcs: string[] };
export type MusicBrainzRelease = Omit<MusicBrainzReleaseSummary, 'score' | 'media'> & {
    groupFirstReleaseDate: LookupDate | null;
    media: { position: number; format: string | null; tracks: MusicBrainzTrack[] }[];
    /** Cover Art Archive front-artwork flag from the release lookup; null when not reported. */
    frontArtwork: boolean | null;
};
export type MusicBrainzRecordingHit = {
    recordingId: string; title: string; lengthMs: number | null; artistCredit: LookupArtistCredit[];
    releases: { releaseId: string; title: string; trackCount: number | null; media: { position: number; format: string | null; trackOffset: number | null }[];
        date: LookupDate | null; country: string | null; primaryType: string | null; secondaryTypes: string[] }[];
};
export type MusicBrainzIsrcResult = { isrc: string; recordings: { recordingId: string; title: string; lengthMs: number | null; releaseIds: string[] }[] };
export type ItunesCollection = { collectionId: string; collectionName: string; artistName: string; trackCount: number | null;
    releaseDate: LookupDate | null; country: string | null; artworkUrl: string | null };
export type ItunesTrack = { trackId: string; collectionId: string; collectionName: string | null; trackName: string; artistName: string;
    discNumber: number | null; discCount: number | null; trackNumber: number | null; trackTimeMillis: number | null };
export type ItunesSearchResult = { collections: ItunesCollection[]; tracks: ItunesTrack[] };
export type CoverArtListing = { releaseId: string; images: { imageId: string; front: boolean; back: boolean; approved: boolean; types: string[]; sizes: (250 | 500 | 1200)[] }[] };

export type LookupSourceFailure = 'notConfigured' | 'busy' | 'rateLimited' | 'unavailable' | 'invalidResponse' | 'cancelled';
const failureCodes: Record<LookupSourceFailure, string> = {
    notConfigured: 'NOT_CONFIGURED', busy: 'BUSY', rateLimited: 'RATE_LIMITED',
    unavailable: 'UNAVAILABLE', invalidResponse: 'INVALID_RESPONSE', cancelled: 'CANCELLED'
};

/** A source outcome other than an answer; its message is a bounded code and never holds a URL, text or body. */
export class MetadataLookupSourceError extends Error {
    constructor(readonly source: MetadataLookupSource, readonly failure: LookupSourceFailure, readonly retryAfterMs: number | null = null) {
        super(`METADATA_LOOKUP_${failureCodes[failure]}`);
        this.name = 'MetadataLookupSourceError';
    }
}

export type LookupInputProblem = 'url' | 'empty' | 'tooLong' | 'invalidText' | 'identifier';
/** Input refused before anything is sent: no gate, DNS or request happens. */
export class MetadataLookupInputError extends Error {
    constructor(readonly reason: LookupInputProblem) {
        super(`METADATA_LOOKUP_INPUT_${reason.replace(/[A-Z]/g, letter => `_${letter}`).toUpperCase()}`);
        this.name = 'MetadataLookupInputError';
    }
}

